{
  "overall_decision": "manual_review",
  "chapters": [
    {
      "chapter_id": "1B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0011",
          "reason": "Secondary analysis with mixed expert views; treat as corroborative context for the F-35 debate, not core proof of Scholz-specific existential-risk judgment."
        },
        {
          "evidence_id": "E0012",
          "reason": "Opposition scrutiny of the procurement choice is accountability context, not independent evidence of the ruler's conduct."
        },
        {
          "evidence_id": "E0013",
          "reason": "Retrospective government summary should corroborate the 2022 record, not carry decisive weight on its own."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct evidence on internal nuclear-safety alternatives and command-and-control review is still thin.",
          "lenses": ["1B.3", "1B.7", "1B.9"],
          "best_source_or_query_direction": "Bundestag defense-committee records or official procurement/safety review material tied to the 2022 F-35 decision",
          "why_it_matters": "It would distinguish alliance maintenance from an affirmatively risk-reducing choice."
        }
      ],
      "reason": "The package fairly presents Scholz's limited but real 2022 choices on nuclear sharing, arms-control posture, and crisis de-escalation, while also preserving that most evidence is government-level rather than direct nuclear-command evidence. The main weakness is attribution granularity, not a missing factual frame."
    },
    {
      "chapter_id": "2B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [
        {
          "gap": "Internal cabinet deliberations and precise alternative options around the Ukraine response are not visible.",
          "lenses": ["2B.1", "2B.7", "2B.9"],
          "best_source_or_query_direction": "Cabinet-adjacent records, parliamentary debates, or contemporaneous peace-process reporting on spring 2022 policy choices",
          "why_it_matters": "It would sharpen attribution for restraint versus escalation in the war response."
        }
      ],
      "reason": "The chapter is well supported: it shows both restraint and escalation, including diplomacy, sanctions, defensive aid, and legal-accountability actions. The contrary evidence is preserved, and the remaining limitation is mainly internal decision visibility."
    },
    {
      "chapter_id": "3B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [
        {
          "gap": "Most policing and complaint-handling evidence is Länder-level, so direct Scholz attribution remains limited.",
          "lenses": ["3B.1", "3B.2", "3B.4", "3B.5"],
          "best_source_or_query_direction": "Federal interior-ministry oversight records and federal complaint/anti-discrimination implementation data",
          "why_it_matters": "It would clarify whether national-level policy materially improved the domestic-safety environment."
        }
      ],
      "reason": "This is a fair mixed record: open constitutional protections, some positive reform steps, one severe police incident, and accountability gaps. The package does not overstate national-ruler control over decentralized policing."
    },
    {
      "chapter_id": "4B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0034",
          "reason": "This is inherited baseline from 2021, not 2022 Scholz conduct; it should stay as context only."
        },
        {
          "evidence_id": "E0035",
          "reason": "Electoral review procedure is institutional context, not direct ruler action."
        },
        {
          "evidence_id": "E0036",
          "reason": "Constitutional-court protection of opposition norms is evidence of the legal environment, not a Scholz-initiated democratic reform."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct evidence of 2022 Scholz-led democratic strengthening is thinner than evidence of institutional baseline and judicial constraint.",
          "lenses": ["4B.1", "4B.4", "4B.10"],
          "best_source_or_query_direction": "Federal cabinet and coalition records on democratic-participation and oversight reforms",
          "why_it_matters": "It would separate inherited resilience from ruler-specific contribution."
        }
      ],
      "reason": "The package fairly shows a resilient democratic environment with no serious evidence of manipulation, entrenchment, or term-rule abuse. Most material is institutional, but that matches the actual 2022 record rather than constituting a defect."
    },
    {
      "chapter_id": "5B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0054",
          "reason": "Inflation outcome data is important context, but it is not direct proof of Scholz-specific economic competence."
        },
        {
          "evidence_id": "E0055",
          "reason": "GDP growth is a broad outcome measure and should not be treated as ruler-specific execution evidence."
        },
        {
          "evidence_id": "E0056",
          "reason": "Real-wage decline is material welfare context, but attribution is largely shock-driven rather than chancellor-specific."
        },
        {
          "evidence_id": "E0058",
          "reason": "Poverty-risk stability is a background outcome, not a direct policy-performance finding."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct chancellor-level evidence on personnel selection, correction after failure, and anti-capture choices remains limited.",
          "lenses": ["5B.2", "5B.5", "5B.7"],
          "best_source_or_query_direction": "Staffing, audit, and coordination records tied to the energy-crisis response and economic ministries",
          "why_it_matters": "It would clarify whether the response was only broad crisis management or also disciplined executive steering."
        }
      ],
      "reason": "The package supports a mixed but credible economic-response record: large-scale crisis relief, strong external assessments of timeliness, and clear limits from external shocks. It is fair so long as macro outcomes are treated as context, not sole proof of merit or failure."
    },
    {
      "chapter_id": "6B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0071",
          "reason": "Inflation data is useful welfare context, but not direct proof of ruler-specific social-policy performance."
        },
        {
          "evidence_id": "E0073",
          "reason": "Real-earnings decline is outcome context; it should not be used as a direct causal finding against Scholz alone."
        },
        {
          "evidence_id": "E0074",
          "reason": "Poverty-risk stability is a broad outcome indicator and belongs as context rather than direct ruler conduct."
        }
      ],
      "material_gaps": [
        {
          "gap": "Post-enactment delivery quality and longer-run durability of the reforms are not fully shown in the 2022 package.",
          "lenses": ["6B.5", "6B.9", "6B.10"],
          "best_source_or_query_direction": "Implementation evaluations and 2023 follow-up reports on Bürgergeld, Wohngeld Plus, and refugee integration",
          "why_it_matters": "It would distinguish enacted policy from measurable welfare improvement."
        }
      ],
      "reason": "The evidence fairly presents substantial social-support action, especially for refugees, low-income households, and energy shock mitigation, while also preserving that the year did not deliver transformative household gains."
    },
    {
      "chapter_id": "7B",
      "decision": "manual_review",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0075",
          "reason": "This is a reported denial, not an independent finding of honesty or dishonesty."
        },
        {
          "evidence_id": "E0077",
          "reason": "This records allegations and a hearing stalemate, not a proven integrity finding."
        },
        {
          "evidence_id": "E0078",
          "reason": "Investigative suspicion about concealed meetings is relevant context, but not proof of concealment."
        },
        {
          "evidence_id": "E0080",
          "reason": "The appellate disclosure ruling is procedural context, not a truthfulness adjudication."
        },
        {
          "evidence_id": "E0082",
          "reason": "Interpretive reporting on memory lapses should not be treated as a legal finding."
        },
        {
          "evidence_id": "E0083",
          "reason": "Protocol release is transparency context, but it does not settle the underlying honesty question."
        },
        {
          "evidence_id": "E0084",
          "reason": "No-prosecution output is not affirmative evidence of integrity; it only limits what can be proven."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct primary evidence on assets, gifts, family benefit, hidden conflicts, or formal self-dealing is missing.",
          "lenses": ["7B.3", "7B.4", "7B.9"],
          "best_source_or_query_direction": "Original Bundestag transcripts, Hamburg committee records, and official disclosure or ethics filings tied to the Cum-Ex/Warburg episode",
          "why_it_matters": "Without personal-nexus proof, the chapter can describe controversy but cannot firmly place Scholz on the integrity scale."
        },
        {
          "gap": "The record remains allegation-heavy rather than adjudication-heavy on deception and obstruction.",
          "lenses": ["7B.2", "7B.6", "7B.7"],
          "best_source_or_query_direction": "Court findings, prosecutorial records, or authenticated committee documents",
          "why_it_matters": "A stable chapter judgment needs more than repeated denials and press scrutiny."
        }
      ],
      "reason": "This is the one chapter that is not yet fully stable. The package fairly captures the Cum-Ex controversy and the scrutiny around it, but it does not supply enough direct personal-nexus evidence to distinguish reputational controversy from proven dishonesty, self-dealing, or obstruction."
    },
    {
      "chapter_id": "8B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0100",
          "reason": "Expert-commission staffing is useful implementation context, but it does not directly show Scholz personally selecting or managing personnel."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct evidence on Scholz's personnel selection, correction of underperformers, and internal discipline is thinner than evidence on program design and rollout.",
          "lenses": ["8B.4", "8B.5", "8B.8"],
          "best_source_or_query_direction": "Cabinet minutes, staffing changes, budget-execution records, or implementation audits tied to the 2022 program",
          "why_it_matters": "It would confirm whether the program was only announced well or also driven through with sustained executive control."
        }
      ],
      "reason": "The program-to-implementation chain is solid enough to present fairly: coalition program, crisis adaptation, enacted reforms, cabinet coordination, and some outcome evidence. The remaining weakness is personnel-and-follow-through granularity, not the basic narrative."
    }
  ]
}
